mapper.select:
SELECT * FROM (SELECT D.APPSERIALNO, F.CUSTNO, F.APDT, D.FILENO AS fileno, F.FUNDACCT, F.INVNM, F.INVTP, F.APKIND, IBF_GET_PARAMNAME('SYSTEM','APKIND',F.APKIND) AS apkindName, D.ORIGINAL AS ifOriginal, D.ISFULL AS ifalldocument, D.ISSCAN AS isscan, D.FILED AS ifsaved, D.KEEPADDRESS, D.ATTACH AS isupload, D.SALESACCMANAGER, D.REMARK AS remarkinfo, F.INSERTTIMESTAMP, CE.VOICERECORD, DC.INVPRTP FROM APPFDACBLOTTER F, DS_CUSTINFODATA D, CUSTINFOEX CE, DS_CUSTCLASSINFO DC WHERE F.SERIALNO = D.APPSERIALNO AND F.CUSTNO = CE.CUSTNO AND F.CUSTNO = DC.CUSTNO AND F.APPLYST NOT IN ('F', 'C') GROUP BY F.CUSTNO, F.APDT, D.FILENO, F.FUNDACCT, F.INVNM, F.INVTP, F.APKIND, D.APPSERIALNO, D.ORIGINAL, D.ISFULL, D.ISSCAN, D.FILED, D.KEEPADDRESS, D.ATTACH, D.SALESACCMANAGER, D.REMARK, F.INSERTTIMESTAMP, CE.VOICERECORD, DC.INVPRTP UNION ALL SELECT D.APPSERIALNO, F.CUSTNO, F.APDT, D.FILENO AS fileno, F.FUNDACCT, F.INVNM, F.INVTP, F.APKIND, IBF_GET_PARAMNAME('SYSTEM','APKIND',F.APKIND) AS apkindName, D.ORIGINAL AS ifOriginal, D.ISFULL AS ifalldocument, D.ISSCAN AS isscan, D.FILED AS ifsaved, D.KEEPADDRESS, D.ATTACH AS isupload, D.SALESACCMANAGER, D.REMARK AS remarkinfo , F.INSERTTIMESTAMP, CE.VOICERECORD, DC.INVPRTP FROM H_APPFDACBLOTTER F, DS_CUSTINFODATA D, CUSTINFOEX CE, DS_CUSTCLASSINFO DC WHERE F.SERIALNO = D.APPSERIALNO AND F.CUSTNO = CE.CUSTNO AND F.CUSTNO = DC.CUSTNO GROUP BY F.CUSTNO, D.APPSERIALNO, F.APDT, D.FILENO, F.FUNDACCT, F.INVNM, F.INVTP, F.APKIND, D.ORIGINAL, D.ISFULL, D.ISSCAN, D.FILED, D.KEEPADDRESS, D.ATTACH, D.SALESACCMANAGER, D.REMARK, F.INSERTTIMESTAMP, CE.VOICERECORD, DC.INVPRTP) DT WHERE 1 = 1
AND APDT BETWEEN #{sp.strDate} AND #{sp.endDate}
AND FILENO like '%'|| #{sp.fileno}||'%'
AND FUNDACCT like '%'|| #{sp.fundacco}||'%'
AND INVNM like '%'|| #{sp.invnm}||'%'
AND CUSTNO = #{sp.custno}
AND KEEPADDRESS like '%'|| #{sp.keepaddress}||'%'
AND SALESACCMANAGER '%'|| #{sp.salesaccmanager}||'%'
AND APKIND = #{sp.apkind}
AND IFORIGINAL = #{sp.isoriginal}
AND IFALLDOCUMENT = #{sp.isalldoc}
AND ISSCAN = #{sp.isscan}
AND IFSAVED = #{sp.issaved}
AND ISUPLOAD = #{sp.isupload}
ORDER BY DT.INSERTTIMESTAMP DESC

SELECT * FROM (SELECT D.APPSERIALNO, F.CUSTNO, F.APDT, D.FILENO AS fileno, F.FUNDACCT, F.INVNM, F.INVTP, F.APKIND, IBF_GET_PARAMNAME('SYSTEM','APKIND',F.APKIND) AS apkindName, D.ORIGINAL AS ifOriginal, D.ISFULL AS ifalldocument, D.ISSCAN AS isscan, D.FILED AS ifsaved, D.KEEPADDRESS, D.ATTACH AS isupload, D.SALESACCMANAGER, D.REMARK AS remarkinfo, F.INSERTTIMESTAMP, CE.VOICERECORD, DC.INVPRTP FROM APPFDACBLOTTER F, DS_CUSTINFODATA D, CUSTINFOEX CE, DS_CUSTCLASSINFO DC WHERE F.SERIALNO = D.APPSERIALNO AND F.CUSTNO = CE.CUSTNO AND F.CUSTNO = DC.CUSTNO AND F.APPLYST NOT IN ('F', 'C') GROUP BY F.CUSTNO, F.APDT, D.FILENO, F.FUNDACCT, F.INVNM, F.INVTP, F.APKIND, D.APPSERIALNO, D.ORIGINAL, D.ISFULL, D.ISSCAN, D.FILED, D.KEEPADDRESS, D.ATTACH, D.SALESACCMANAGER, D.REMARK, F.INSERTTIMESTAMP, CE.VOICERECORD, DC.INVPRTP UNION ALL SELECT D.APPSERIALNO, F.CUSTNO, F.APDT, D.FILENO AS fileno, F.FUNDACCT, F.INVNM, F.INVTP, F.APKIND, IBF_GET_PARAMNAME('SYSTEM','APKIND',F.APKIND) AS apkindName, D.ORIGINAL AS ifOriginal, D.ISFULL AS ifalldocument, D.ISSCAN AS isscan, D.FILED AS ifsaved, D.KEEPADDRESS, D.ATTACH AS isupload, D.SALESACCMANAGER, D.REMARK AS remarkinfo , F.INSERTTIMESTAMP, CE.VOICERECORD, DC.INVPRTP FROM H_APPFDACBLOTTER F, DS_CUSTINFODATA D, CUSTINFOEX CE, DS_CUSTCLASSINFO DC WHERE F.SERIALNO = D.APPSERIALNO AND F.CUSTNO = CE.CUSTNO AND F.CUSTNO = DC.CUSTNO GROUP BY F.CUSTNO, D.APPSERIALNO, F.APDT, D.FILENO, F.FUNDACCT, F.INVNM, F.INVTP, F.APKIND, D.ORIGINAL, D.ISFULL, D.ISSCAN, D.FILED, D.KEEPADDRESS, D.ATTACH, D.SALESACCMANAGER, D.REMARK, F.INSERTTIMESTAMP, CE.VOICERECORD, DC.INVPRTP) DT WHERE 1 = 1
AND APDT BETWEEN #{sp.strDate} AND #{sp.endDate}
AND FILENO like '%'|| #{sp.fileno}||'%'
AND FUNDACCT like '%'|| #{sp.fundacco}||'%'
AND INVNM like '%'|| #{sp.invnm}||'%'
AND CUSTNO = #{sp.custno}
AND KEEPADDRESS like '%'|| #{sp.keepaddress}||'%'
AND SALESACCMANAGER '%'|| #{sp.salesaccmanager}||'%'
AND APKIND = #{sp.apkind}
AND IFORIGINAL = #{sp.isoriginal}
AND IFALLDOCUMENT = #{sp.isalldoc}
AND ISSCAN = #{sp.isscan}
AND IFSAVED = #{sp.issaved}
AND ISUPLOAD = #{sp.isupload}
ORDER BY DT.INSERTTIMESTAMP DESC
